using System;using System.IO;using System.Reflection;using System.Runtime.Serialization;using System.Collections.Generic;using ElementalHearts;using RimWorld;using Verse;
class ManifestHairRegression {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
