 static int Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string n=new AssemblyName(e.Name).Name;string p=n=="ElementalHearts"?args[1]:n=="0Harmony"?args[2]:Path.Combine(args[0],n+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};try{typeof(ManifestHairRegression).GetMethod("Run",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static ThingDef Def(ApparelProperties a){var d=Empty<ThingDef>();d.apparel=a;return d;}
 static void Run(){
  typeof(DefOfHelper).GetField("bindingNow",BindingFlags.NonPublic|BindingFlags.Static).SetValue(null,true);
  RenderSkipFlagDefOf.Hair=new RenderSkipFlagDef{defName="Hair"};RenderSkipFlagDefOf.Beard=new RenderSkipFlagDef{defName="Beard"};RenderSkipFlagDefOf.None=new RenderSkipFlagDef{defName="None"};BodyPartGroupDefOf.FullHead=new BodyPartGroupDef{defName="FullHead"};BodyPartGroupDefOf.UpperHead=new BodyPartGroupDef{defName="UpperHead"};
  var full=new ApparelProperties{renderSkipFlags=null,bodyPartGroups=new List<BodyPartGroupDef>{BodyPartGroupDefOf.FullHead}};var upper=new ApparelProperties{renderSkipFlags=null,bodyPartGroups=new List<BodyPartGroupDef>{BodyPartGroupDefOf.UpperHead}};Check(ManifestHairRules.Conceals(full,false)&&ManifestHairRules.Conceals(full,true)&&ManifestHairRules.Conceals(upper,false)&&!ManifestHairRules.Conceals(upper,true),"native full/upper head fallback differs");
